from dataclasses import dataclass, field
from typing import Optional, Literal

@dataclass
class VoiceConfig:
    language_code: str = "en-US"
    name: Optional[str] = None
    ssml_gender: Optional[Literal["SSML_VOICE_GENDER_UNSPECIFIED", "MALE", "FEMALE", "NEUTRAL"]] = None

@dataclass
class AudioConfig:
    audio_encoding: Literal["MP3", "LINEAR16", "OGG_OPUS"] = "MP3"
    speaking_rate: Optional[float] = None
    pitch: Optional[float] = None
    volume_gain_db: Optional[float] = None
    sample_rate_hertz: Optional[int] = None

@dataclass
class SynthesisRequest:
    text: Optional[str] = None
    ssml: Optional[str] = None
    voice: VoiceConfig = field(default_factory=VoiceConfig)
    audio_config: AudioConfig = field(default_factory=AudioConfig)

@dataclass
class SynthesisResponse:
    audio_content: bytes

@dataclass
class ListVoicesResponse:
    voices: list

from google.cloud import texttospeech

def get_tts_client():
    """Initializes and returns a Google Cloud Text-to-Speech client."""
    return texttospeech.TextToSpeechClient()

from speech_client import get_tts_client
from speech_models import ListVoicesResponse, VoiceConfig
from google.cloud import texttospeech

def select_voice(language_code: str, name: str = None) -> ListVoicesResponse:
    client = get_tts_client()

    # The client can also be used to list the client's supported voices.
    voices = client.list_voices(language_code=language_code).voices

    if name:
        filtered_voices = [voice for voice in voices if voice.name == name]
        return ListVoicesResponse(voices=filtered_voices)

    return ListVoicesResponse(voices=voices)

def save_audio(audio_content: bytes, file_path: str):
    with open(file_path, "wb") as out:
        out.write(audio_content)

from googleapiclient import discovery

def check_safety(text: str) -> dict:
    client = discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey="YOUR_API_KEY"  # Replace with your Perspective API key
    )

    analyze_request = {
        'comment': {'text': text},
        'requestedAttributes': {'TOXICITY': {}}
    }

    response = client.comments().analyze(body=analyze_request).execute()
    return response
